from math import sqrt
from statistics import mean, pstdev, stdev

eps_a = eps_o = 1e-3
lam_a = lam_o = 1.0
B = 1
sites = ["r1", "r2", "r3"]
episodes = [
    {
        "id": "j1", "contact": True,
        "a0": [1.0, 2.0], "o0": [10.0, 20.0],
        "ar": {
            "r1": [2.0, 2.0], "r2": [1.5, 2.5], "r3": [1.0, 2.0]
        },
        "or": {
            "r1": [11.0, 20.0], "r2": [10.0, 22.0], "r3": [10.0, 20.0]
        },
    },
    {
        "id": "j2", "contact": False,
        "a0": [3.0, 4.0], "o0": [12.0, 22.0],
        "ar": {
            "r1": [3.0, 5.0], "r2": [3.5, 4.5], "r3": [3.0, 4.0]
        },
        "or": {
            "r1": [12.0, 24.0], "r2": [13.0, 23.0], "r3": [12.0, 22.0]
        },
    },
]

def mse(x, y):
    return mean((a - b) ** 2 for a, b in zip(x, y))

def pixel_l1(x, y):
    return mean(abs(a - b) for a, b in zip(x, y))

def ranks(values):
    order = sorted(range(len(values)), key=lambda i: values[i])
    out = [0] * len(values)
    for rank, i in enumerate(order, 1):
        out[i] = rank
    return out

def spearman(x, y):
    rx, ry = ranks(x), ranks(y)
    mx, my = mean(rx), mean(ry)
    num = sum((a - mx) * (b - my) for a, b in zip(rx, ry))
    den = sqrt(sum((a - mx) ** 2 for a in rx) * sum((b - my) ** 2 for b in ry))
    return None if den == 0 else num / den

local = {"r1": [1.0, 1.0], "r2": [0.25, 0.25], "r3": [0.0625, 0.0625]}
all_action_values = [v for e in episodes for v in e["a0"]]
flat_mean = mean(all_action_values)
sigma_a2_readings = {
    "flattened_population": mean((v - flat_mean) ** 2 for v in all_action_values),
    "per_coordinate_population": mean(
        pstdev([e["a0"][p] for e in episodes]) ** 2
        for p in range(len(episodes[0]["a0"]))
    ),
    "flattened_sample": sum((v - flat_mean) ** 2 for v in all_action_values) / (len(all_action_values) - 1),
    "per_coordinate_sample": mean(
        stdev([e["a0"][p] for e in episodes]) ** 2
        for p in range(len(episodes[0]["a0"]))
    ),
}
sigma_o_readings = {
    "per_pixel_population": mean(
        pstdev([e["o0"][p] for e in episodes])
        for p in range(len(episodes[0]["o0"]))
    ),
    "per_pixel_sample": mean(
        stdev([e["o0"][p] for e in episodes])
        for p in range(len(episodes[0]["o0"]))
    ),
}

for a_name, sigma_a2 in sigma_a2_readings.items():
    for o_name, sigma_o in sigma_o_readings.items():
        rows = {}
        for r in sites:
            da = [mse(e["a0"], e["ar"][r]) / max(sigma_a2, eps_a ** 2) for e in episodes]
            do = [pixel_l1(e["o0"], e["or"][r]) / max(sigma_o, eps_o) for e in episodes]
            combined = [lam_a * a + lam_o * o for a, o in zip(da, do)]
            rows[r] = {
                "d_a": da, "d_o": do, "episode_C": combined,
                "C": mean(combined), "L": mean(local[r]),
            }

        def selection(key):
            return sorted(sites, key=lambda r: (-rows[r][key], r))[:B]

        print("reading=", a_name + "+" + o_name,
              "sigma_a2=", sigma_a2, "sigma_o=", sigma_o)
        for r in sites:
            print(r, rows[r])
        print("C_rank_desc=", sorted(sites, key=lambda r: (-rows[r]["C"], r)))
        print("L_rank_desc=", sorted(sites, key=lambda r: (-rows[r]["L"], r)))
        print("mechanism_top_B=", selection("C"), "naive_top_B=", selection("L"))
        print("rho_all=", spearman([rows[r]["C"] for r in sites], [rows[r]["L"] for r in sites]))
        for contact in (True, False):
            idx = [i for i, e in enumerate(episodes) if e["contact"] == contact]
            cvals = [mean([rows[r]["episode_C"][i] for i in idx]) for r in sites]
            lvals = [rows[r]["L"] for r in sites]
            print("contact=", contact, "C=", cvals, "L=", lvals,
                  "rho=", spearman(cvals, lvals))
        print("---")
print("synthetic_joint_stress_residual_loss_when_one_site_protected=",
      {"r1": 100, "r2": 20, "r3": 5},
      "single_site_C_top=", "r2 under flattened_population+per_pixel_population",
      "joint_best_lower_loss=", "r3")
print("synthetic_site_count_cost_stress=",
      {"same_B_site": 1, "schedule_A_bytes": 9, "schedule_B_bytes": 1,
       "bytes_ratio": 9},
      "site_count_does_not_fix_bytes=True")
print("nominal_1_2_gpu_day_hours_if_gpu_day_means_24h=", 1.2 * 24,
      "memory_equivalence_unestablished=True")
